// This type alias is provided for backwards compatibility with existing code that references the prior non-generic stream type by name.
type Shard_WatchClient = grpc.ServerStreamingClient[Event]

// ShardServer is the server API for Shard service.
// All implementations must embed UnimplementedShardServer
// for forward compatibility.
//
// Shard is served by the core: by shardd on desktops (unix socket
// or named pipe) and in-process on Android. The Flutter app is a client.
type ShardServer interface {
	// Vault lifecycle.
	GetState(context.Context, *Empty) (*State, error)
	CreateVault(context.Context, *CreateVaultRequest) (*State, error)
	ImportVault(context.Context, *ImportVaultRequest) (*State, error)
	Unlock(context.Context, *UnlockRequest) (*State, error)
	LockVault(context.Context, *Empty) (*State, error)
	ChangePassword(context.Context, *ChangePasswordRequest) (*Empty, error)
	// PermissionDenied unless the password opens the vault file (e.g. before
	// saving it for fingerprint unlock).
	CheckPassword(context.Context, *CheckPasswordRequest) (*Empty, error)
	ExportVault(context.Context, *Empty) (*VaultFile, error)
	// Storages.
	BackendTypes(context.Context, *Empty) (*BackendTypesReply, error)
	AddBackend(context.Context, *AddBackendRequest) (*Backend, error)
	SetBackendEnabled(context.Context, *SetBackendEnabledRequest) (*Backend, error)
	RenameBackend(context.Context, *RenameBackendRequest) (*Backend, error)
	// Deletes a disabled storage no file uses any more (Repair moves data off).
	// With force it goes even then: its shards count as lost (for a storage
	// that is gone for good); Repair rebuilds what other shards allow.
	RemoveBackend(context.Context, *RemoveBackendRequest) (*Empty, error)
	// Browser sign-in for OAuth storages: the first reply carries the URL to
	// open on this device, the last one the token for AddBackend params.
	Authorize(*AuthorizeRequest, grpc.ServerStreamingServer[AuthorizeReply]) error
	// Signs in to the account of an existing OAuth storage again (revoked or
	// expired token) and saves the new token; ID and data stay. Replies: the
	// URL to open, then the account (token not sent). Refuses another account.
	Reconnect(*IdRequest, grpc.ServerStreamingServer[AuthorizeReply]) error
	Status(context.Context, *Empty) (*StatusReply, error)
	// Recent core events: storage failures, sync errors, mounts.
	Logs(context.Context, *LogsRequest) (*LogsReply, error)
	ClearLogs(context.Context, *Empty) (*Empty, error)
	// Desktop: the folder the vault is shown in (empty = do not mount).
	// Remounts at once when unlocked; kept for later starts.
	SetMountPoint(context.Context, *PathRequest) (*State, error)
	// Desktop: locks the vault and stops the daemon (the app starts it again
	// when it reconnects).
	Shutdown(context.Context, *Empty) (*Empty, error)
	// Files.
	List(context.Context, *PathRequest) (*ListReply, error)
	Search(context.Context, *SearchRequest) (*ListReply, error)
	Stat(context.Context, *PathRequest) (*Entry, error)
	Mkdir(context.Context, *PathRequest) (*Empty, error)
	Remove(context.Context, *RemoveRequest) (*Empty, error)
	Rename(context.Context, *RenameRequest) (*Empty, error)
	Upload(context.Context, *UploadRequest) (*UploadReply, error)
	Download(context.Context, *DownloadRequest) (*Empty, error)
	// Keeping files on this device.
	Pin(context.Context, *PathRequest) (*Empty, error)
	Unpin(context.Context, *PathRequest) (*Empty, error)
	// Locks: who has a file open for writing.
	LockHolder(context.Context, *PathRequest) (*LockInfo, error)
	Locks(context.Context, *PathsRequest) (*LocksReply, error)
	// Maintenance.
	Sync(context.Context, *Empty) (*Empty, error)
	// Checks every shard, rewrites lost ones, re-encodes after a k/m change.
	Repair(context.Context, *RepairRequest) (*RepairReply, error)
	// Removes data no file uses (after a grace period, see GCRequest).
	GC(context.Context, *GCRequest) (*GCReply, error)
	// k/m for new files; Repair re-encodes existing ones.
	SetRedundancy(context.Context, *SetRedundancyRequest) (*Empty, error)
	// Password safe: passwords, SSH and web3 keys in groups. Lists carry no
	// secret fields; GetSecret opens one entry (show it, then forget it).
	ListSecrets(context.Context, *Empty) (*SecretsReply, error)
	GetSecret(context.Context, *IdRequest) (*SecretEntry, error)
	// Creates (empty id) or replaces an entry; returns it without secrets.
	PutSecret(context.Context, *SecretEntry) (*SecretEntry, error)
	DeleteSecret(context.Context, *IdRequest) (*Empty, error)
	PutSecretGroup(context.Context, *SecretGroup) (*SecretGroup, error)
	// Entries of a removed group stay, without a group.
	DeleteSecretGroup(context.Context, *IdRequest) (*Empty, error)
	// Public key of a private key, for the editor; nothing is stored.
	DeriveKey(context.Context, *DeriveKeyRequest) (*DerivedKey, error)
	// Current codes of every TOTP entry (the secrets stay in the core).
	TotpCodes(context.Context, *Empty) (*TotpCodesReply, error)
	// Removes a used recovery code from a TOTP entry; returns it without secrets.
	UseRecoveryCode(context.Context, *RecoveryCodeRequest) (*SecretEntry, error)
	// Reads a TOTP secret / otpauth:// URI and pasted recovery codes, for
	// the editor; nothing is stored.
	CheckTotp(context.Context, *CheckTotpRequest) (*TotpPreview, error)
	// Finds the otpauth://totp/ links in pasted text and expands Google
	// Authenticator exports (otpauth-migration://); nothing is stored.
	ReadTotpLinks(context.Context, *TotpLinksRequest) (*TotpLinksReply, error)
	// Imports an export of another password manager: KeePass (.kdbx, XML,
	// CSV), KeePassXC, Chrome / Edge / Brave / Opera, Firefox, Safari,
	// Bitwarden (CSV, unencrypted JSON), 1Password, LastPass, Dashlane,
	// Proton Pass, NordPass CSV. With dry_run only the preview is returned.
	ImportSecrets(context.Context, *SecretImportRequest) (*SecretImportReply, error)
	// Connected apps (docs/CONNECTOR.md): pairing requests waiting for the
	// user, apps paired on this device, and the records apps keep in the
	// vault (shared by all devices).
	ListApps(context.Context, *Empty) (*AppsReply, error)
	DecidePairing(context.Context, *DecidePairingRequest) (*Empty, error)
	// Forgets a pairing on this device; the app's records stay.
	RevokeApp(context.Context, *IdRequest) (*Empty, error)
	// Sets the scopes of a pairing; only scopes it has can be kept (removing
	// "passwords" takes the password store away without unpairing).
	SetAppScopes(context.Context, *SetAppScopesRequest) (*Empty, error)
	// Deletes every record of an app (id = app id) on all devices.
	DeleteAppData(context.Context, *IdRequest) (*Empty, error)
	// Events for live UI updates.
	Watch(*Empty, grpc.ServerStreamingServer[Event]) error
	mustEmbedUnimplementedShardServer()
}

